    const STORAGE_KEY = "SOHAM_TCS_2026_MASTER_TRACKER_V1";

    function getDefaultState() {
      return {
        currentPage: "cover",
        currentDay: 1,
        dayViewTab: "unified",
        settings: {
          dailyStartTime: "07:30",
          targetFinish: "22:30",
          targetMins: "150",
          mockScore: "",
          manualStreak: ""
        },
        fiveDayBlocks: {},
        preCodingChecks: {},
        days: {},
        resumeChecks: {},
        resumeNotes: {}
      };
    }

    let state = getDefaultState();

    function loadState() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
          const parsed = JSON.parse(raw);
          state = Object.assign(getDefaultState(), parsed);
          state.settings = Object.assign(getDefaultState().settings, parsed.settings || {});
        }
      } catch (e) {
        console.warn("Storage load fallback:", e);
      }
    }

    function saveState(toastText) {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
        if (toastText) showToast(toastText);
      } catch (e) {
        console.warn("Storage save fallback:", e);
      }
    }

    function getDayState(dayNum) {
      if (!state.days[dayNum]) {
        state.days[dayNum] = {
          dayDone: false,
          q1: false,
          q2: false,
          q3: false,
          sideQuest: false,
          aptLearn: false,
          aptTimed: false,
          aptSampleAnswered: null,
          csConcept: false,
          speakingDone: false,
          puzzleSolved: false,
          puzzleShowHint: false,
          puzzleShowAns: false,
          exSets: {},
          alsoDoDone: false,
          scWorkout: false,
          scBlock1: false,
          scBlock2: false,
          scRecall: false,
          scPhone: false,
          scSleep: false,
          cookMorning: false,
          cookProtein: false,
          cookDinner: false,
          walkPostMeal: false,
          hardestBug: "",
          errorLog: "",
          domainNotes: "",
          speakingNotes: "",
          oneWin: "",
          tomorrowAction: ""
        };
      }
      return state.days[dayNum];
    }

    function showToast(msg) {
      const box = document.getElementById("toast-box");
      const msgEl = document.getElementById("toast-msg");
      if (!box || !msgEl) return;
      msgEl.textContent = msg;
      box.classList.remove("hidden");
      clearTimeout(window.__toastTimer);
      window.__toastTimer = setTimeout(() => {
        box.classList.add("hidden");
      }, 1800);
    }

    function computeMetrics() {
      let daysDone = 0;
      let problemsSolved = 0;
      let strengthDone = 0;
      let currentStreak = 0;
      let bestStreak = 0;

      for (let pd = 1; pd <= 2; pd++) {
        for (let q = 1; q <= 3; q++) {
          if (state.preCodingChecks[`pre_${pd}_q${q}`]) problemsSolved++;
        }
      }

      for (let d = 1; d <= 58; d++) {
        const ds = state.days[d];
        const meta = APP_DATA.days[d - 1];
        const isStrength = meta.discipline.workoutType.startsWith("STRENGTH");
        if (ds) {
          if (ds.q1) problemsSolved++;
          if (ds.q2) problemsSolved++;
          if (ds.q3) problemsSolved++;
          if (ds.scWorkout && isStrength) strengthDone++;
          const completed = ds.dayDone || (ds.q1 && ds.q2 && ds.q3 && ds.scWorkout && ds.scBlock1);
          if (completed) {
            daysDone++;
            currentStreak++;
            if (currentStreak > bestStreak) bestStreak = currentStreak;
          } else {
            currentStreak = 0;
          }
        } else {
          currentStreak = 0;
        }
      }
      return { daysDone, problemsSolved, strengthDone, bestStreak };
    }

    function getDayCompletionPercent(dayNum) {
      const ds = getDayState(dayNum);
      const checks = [
        ds.q1, ds.q2, ds.q3, ds.sideQuest,
        ds.aptLearn, ds.aptTimed, ds.csConcept, ds.speakingDone,
        ds.puzzleSolved,
        ds.scWorkout, ds.scBlock1, ds.scBlock2, ds.scRecall, ds.scPhone, ds.scSleep
      ];
      const doneCount = checks.filter(Boolean).length;
      if (ds.dayDone) return 100;
      return Math.round((doneCount / checks.length) * 100);
    }

    let speakingTimerInterval = null;
    let speakingSecondsLeft = 90;
    let gymTimerInterval = null;
    let gymSecondsLeft = 75;

    function clearActiveTimers() {
      if (speakingTimerInterval) { clearInterval(speakingTimerInterval); speakingTimerInterval = null; }
      if (gymTimerInterval) { clearInterval(gymTimerInterval); gymTimerInterval = null; }
    }

    function formatTimer(sec) {
      const m = Math.floor(sec / 60);
      const s = sec % 60;
      return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    }

    function getMultiPageTargetFile(page, dayNum) {
      const inDaysSubdir = window.location.pathname.replace(/\\/g, "/").includes("/days/");
      const prefix = inDaysSubdir ? "../" : "";
      const daysPrefix = inDaysSubdir ? "" : "days/";
      if (page === "cover") return prefix + "index.html";
      if (page === "cal-nov") return prefix + "calendar-nov.html";
      if (page === "cal-dec") return prefix + "calendar-dec.html";
      if (page === "exercises") return prefix + "exercise-library.html";
      if (page === "coding-overview") return prefix + "coding-roadmap.html";
      if (page === "tcs-overview") return prefix + "tcs-prep.html";
      if (page === "system") return prefix + "discipline-system.html";
      if (page === "resume") return prefix + "resume.html";
      if (page === "resources") return prefix + "resources.html";
      if (page === "pre-coding") {
        const dStr = String(dayNum || 1).padStart(2, "0");
        return daysPrefix + `coding-warmup-${dStr}.html`;
      }
      if (page === "day") {
        const dStr = String(dayNum || state.currentDay || 1).padStart(2, "0");
        return daysPrefix + `day-${dStr}.html`;
      }
      return null;
    }

    function navigateTo(page, dayNum, subTab) {
      clearActiveTimers();
      const prevPage = state.currentPage;
      const prevDay = state.currentDay;
      state.currentPage = page;
      if (dayNum !== undefined && dayNum !== null) {
        state.currentDay = Number(dayNum);
      }
      if (subTab) {
        state.dayViewTab = subTab;
      }
      saveState();
      if (window.__USE_MULTIPAGE_FILES__ && !subTab && (prevPage !== state.currentPage || prevDay !== state.currentDay)) {
        const targetHref = getMultiPageTargetFile(state.currentPage, state.currentDay);
        if (targetHref) {
          window.location.href = targetHref;
          return;
        }
      }
      renderApp();
      window.scrollTo({ top: 0, behavior: "smooth" });
    }

    function initQuickSelect() {
      const sel = document.getElementById("quick-day-select");
      if (!sel) return;
      let html = `<option value="cover">📋 Jump to Page / Day...</option>`;
      html += `<option value="pre-1">Nov 02 (Mon) — Coding Day 01 Warm-up</option>`;
      html += `<option value="pre-2">Nov 03 (Tue) — Coding Day 02 Warm-up</option>`;
      APP_DATA.days.forEach(d => {
        const shortDate = d.dateStr.replace(" 2026", "");
        const colTag = d.isCollegeDay ? " [🎓 College+Cook]" : "";
        html += `<option value="day-${d.day}">Day ${String(d.day).padStart(2, '0')} (${shortDate})${colTag}</option>`;
      });
      sel.innerHTML = html;
      sel.addEventListener("change", (e) => {
        const val = e.target.value;
        if (val === "cover") navigateTo("cover");
        else if (val === "pre-1") navigateTo("pre-coding", 1);
        else if (val === "pre-2") navigateTo("pre-coding", 2);
        else if (val.startsWith("day-")) {
          const dn = parseInt(val.replace("day-", ""), 10);
          navigateTo("day", dn);
        }
      });
    }

