    function createZipBlobFromEntries(entries) {
      const enc = new TextEncoder();
      const localChunks = [];
      const centralChunks = [];
      let offset = 0;

      for (const item of entries) {
        const nameBytes = enc.encode(item.path);
        const data = item.bytes;
        const crc = crc32Bytes(data);
        const size = data.length;

        const lfh = new Uint8Array(30 + nameBytes.length);
        const ldv = new DataView(lfh.buffer);
        ldv.setUint32(0, 0x04034b50, true);
        ldv.setUint16(4, 20, true);
        ldv.setUint16(6, 0x0800, true);
        ldv.setUint16(8, 0, true);
        ldv.setUint16(10, 0, true);
        ldv.setUint16(12, 0x5864, true);
        ldv.setUint32(14, crc, true);
        ldv.setUint32(18, size, true);
        ldv.setUint32(22, size, true);
        ldv.setUint16(26, nameBytes.length, true);
        ldv.setUint16(28, 0, true);
        lfh.set(nameBytes, 30);

        localChunks.push(lfh);
        localChunks.push(data);

        const cdh = new Uint8Array(46 + nameBytes.length);
        const cdv = new DataView(cdh.buffer);
        cdv.setUint32(0, 0x02014b50, true);
        cdv.setUint16(4, 20, true);
        cdv.setUint16(6, 20, true);
        cdv.setUint16(8, 0x0800, true);
        cdv.setUint16(10, 0, true);
        cdv.setUint16(12, 0, true);
        cdv.setUint16(14, 0x5864, true);
        cdv.setUint32(16, crc, true);
        cdv.setUint32(20, size, true);
        cdv.setUint32(24, size, true);
        cdv.setUint16(28, nameBytes.length, true);
        cdv.setUint16(30, 0, true);
        cdv.setUint16(32, 0, true);
        cdv.setUint16(34, 0, true);
        cdv.setUint16(36, 0, true);
        cdv.setUint32(38, 0, true);
        cdv.setUint32(42, offset, true);
        cdh.set(nameBytes, 46);

        centralChunks.push(cdh);
        offset += lfh.length + size;
      }

      let cdSize = 0;
      for (const c of centralChunks) cdSize += c.length;

      const eocd = new Uint8Array(22);
      const edv = new DataView(eocd.buffer);
      edv.setUint32(0, 0x06054b50, true);
      edv.setUint16(4, 0, true);
      edv.setUint16(6, 0, true);
      edv.setUint16(8, entries.length, true);
      edv.setUint16(10, entries.length, true);
      edv.setUint32(12, cdSize, true);
      edv.setUint32(16, offset, true);
      edv.setUint16(20, 0, true);

      return new Blob([...localChunks, ...centralChunks, eocd], { type: "application/zip" });
    }

    function downloadMultiPageZipNow() {
      try {
        const statusEl = document.getElementById("zip-status-msg");
        if (statusEl) {
          statusEl.classList.remove("hidden");
          statusEl.textContent = "Building multi-page website ZIP in browser memory...";
        }
        const entries = buildMultiPageFileEntries();
        const blob = createZipBlobFromEntries(entries);
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "TCS_NQT_2026_Website.zip";
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 5000);
        if (statusEl) {
          statusEl.textContent = "✓ Downloaded TCS_NQT_2026_Website.zip (" + entries.length + " files)! Extract it directly into D:\\TCS nqt -2026 and open index.html.";
        }
        showToast("Downloaded TCS_NQT_2026_Website.zip (" + entries.length + " files)!");
      } catch (err) {
        showToast("ZIP generation error: " + err.message);
      }
    }

    async function installDirectlyToFolder() {
      const statusEl = document.getElementById("zip-status-msg");
      if (!window.showDirectoryPicker) {
        downloadMultiPageZipNow();
        return;
      }
      try {
        const dirHandle = await window.showDirectoryPicker({ mode: "readwrite" });
        if (statusEl) {
          statusEl.classList.remove("hidden");
          statusEl.textContent = "Writing all multi-page website files directly into your selected folder...";
        }
        const entries = buildMultiPageFileEntries();
        const subDirs = {};
        for (const item of entries) {
          const parts = item.path.split("/");
          let currentDir = dirHandle;
          if (parts.length > 1) {
            const folderName = parts[0];
            if (!subDirs[folderName]) {
              subDirs[folderName] = await dirHandle.getDirectoryHandle(folderName, { create: true });
            }
            currentDir = subDirs[folderName];
          }
          const fileName = parts[parts.length - 1];
          const fileHandle = await currentDir.getFileHandle(fileName, { create: true });
          const writable = await fileHandle.createWritable();
          await writable.write(item.bytes);
          await writable.close();
        }
        if (statusEl) {
          statusEl.textContent = "✓ Installed all " + entries.length + " files directly into your folder! Open index.html to start.";
        }
        showToast("Installed all " + entries.length + " website files to folder!");
      } catch (err) {
        if (err && err.name !== "AbortError") {
          downloadMultiPageZipNow();
        }
      }
    }

